package com.xjtu.toolbox.game.xiangqi.rules

/**
 * 局面哈希（Zobrist）。
 *
 * 从 :app 的 `rules/Zobrist.java` 逐字搬过来 —— **数据表一个字节都没改**：
 * 这张表是从华弈2022的开局库提取的，`XiangqiGame` 拿它做重复局面（长将/长捉）判定，
 * 换成自己现生成的一张表虽然也是「合法哈希」，但那是行为变化，不是搬位置。
 *
 * 原文件里 `coordMap` 是 `HashMap<Integer, String>`；这里换成 `Map<Int, String>`，
 * 键值一字不变（`getMoveFromVmove` 只有上游的 vmove 编码在用它）。
 */
object Zobrist {

    fun getMoveFromVmove(vmove: Int): String {
        val first = vmove shr 8
        val second = vmove and 0x00ff
        return coordMap[second] + coordMap[first]
    }

    fun getZobristFromBoard(board: Array<IntArray>, redGo: Boolean): Long {
        var zobrist = 0L
        for (y in 0 until 10) {
            for (x in 0 until 9) {
                val piece = board[y][x]
                if (piece != Piece.EMPTY) {
                    val index = x + y * 9
                    val square = c90[index]
                    zobrist = zobrist xor zobristTable[(piece - 1) * 256 + square].toLong()
                }
            }
        }
        if (redGo) {
            zobrist = zobrist xor zobristPlayer.toLong()
        }
        return zobrist
    }

    private val c90 = intArrayOf(
            0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b,
            0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4a, 0x4b,
